import ReactMarkdown from "react-markdown";
import type { RichSectionData } from "../block-zone/types";
import {
  DEFAULT_RICH_ASPECT,
  imageAspectClass,
  imageFitClass,
  imageFrameClass,
  resolveRichFondo,
  resolveRichImageSide,
  resolveRichMode,
  resolveRichVideoUrl,
  safeHref,
  sectionHeadingClass,
  BLOCK_RADIUS_BUTTON_CLASS,
  BLOCK_RADIUS_CLASS,
  SECTION_ROOT_CLASS,
} from "../block-zone/types";
import HeroFondoVideo from "./hero-fondo-video";

type RichSectionProps = {
  data: RichSectionData;
  isOwner?: boolean;
};

function RichSectionPlaceholder() {
  return (
    <section
      aria-label="Sección de texto"
      className={SECTION_ROOT_CLASS}
    >
      <div className={`${BLOCK_RADIUS_CLASS} border border-border bg-card px-8 py-12 text-center`}>
        <p className="font-heading text-sm text-muted-foreground">
          Sección de texto — agregá el contenido por chat
        </p>
      </div>
    </section>
  );
}

export default function RichSection({
  data,
  isOwner = false,
}: RichSectionProps) {
  if (!data.title && !data.body) {
    return isOwner ? <RichSectionPlaceholder /> : null;
  }

  // Kit-once (#3883): fuera del closed-set → default, nunca explota.
  const imageSide = resolveRichImageSide(data.image_side);
  const mode = resolveRichMode(data.mode);
  const isCenter = data.align === "center";
  const isChecklist = mode === "checklist";
  const isCenteredMode = mode === "centrado";
  const ctaHref = safeHref(data.cta_url);
  const imageUrl =
    typeof data.image_url === "string" && data.image_url.trim()
      ? data.image_url.trim()
      : undefined;
  const hasImage = Boolean(imageUrl);
  // Fondo completo (#4567): solo con media de fondo (imagen o video). Sin media → render normal.
  const videoUrl = resolveRichVideoUrl(data.video_url);
  const isHero =
    resolveRichFondo(data.fondo) === "completo" && (hasImage || Boolean(videoUrl));
  const splitLayout = hasImage && !isCenteredMode;
  // En hero el texto va sobre el overlay: centrado por `align`, aunque haya imagen.
  const textCentered = isCenter && (!hasImage || isHero);

  // Tokens del cuerpo: default byte-idénticos a hoy; hero = tono inverso sobre el overlay.
  const bodyToneClass = isHero
    ? "max-w-none text-base leading-relaxed text-background break-words [&_a]:text-background [&_a]:underline [&_a]:underline-offset-4 [&_a:hover]:opacity-80 [&_strong]:font-semibold [&_strong]:text-background [&_h3]:font-heading [&_h3]:font-semibold [&_h3]:text-background"
    : "max-w-none text-base leading-relaxed text-muted-foreground break-words [&_a]:text-primary [&_a]:underline [&_a]:underline-offset-4 [&_a:hover]:opacity-80 [&_strong]:font-semibold [&_strong]:text-foreground [&_h3]:font-heading [&_h3]:font-semibold [&_h3]:text-foreground";

  const text = (
    <div
      className={[
        "flex min-w-0 flex-col gap-6",
        textCentered ? "items-center text-center" : "",
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {data.title ? (
        <h2 className={sectionHeadingClass(data, isHero ? "inverse" : "default")}>
          {data.title}
        </h2>
      ) : null}

      {data.body ? (
        <div
          className={[
            bodyToneClass,
            isChecklist
              ? [
                  "[&_ul]:list-none [&_ul]:space-y-3 [&_ul]:pl-0",
                  "[&_ol]:list-decimal [&_ol]:pl-5",
                  "[&_li]:relative [&_li]:pl-7",
                  "[&_li]:before:absolute [&_li]:before:left-0 [&_li]:before:top-1.5",
                  "[&_li]:before:size-4 [&_li]:before:rounded-[var(--block-radius-suave,0.125rem)]",
                  "[&_li]:before:border [&_li]:before:border-primary",
                  "[&_li]:before:bg-primary [&_li]:before:content-['']",
                ].join(" ")
              : isHero
                ? "[&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5 [&_li]:marker:text-background"
                : "[&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5 [&_li]:marker:text-primary",
            "[&_blockquote]:border-l-2 [&_blockquote]:border-border [&_blockquote]:pl-4 [&_blockquote]:italic",
            textCentered ? "mx-auto" : "",
          ]
            .filter(Boolean)
            .join(" ")}
        >
          <ReactMarkdown>{data.body}</ReactMarkdown>
        </div>
      ) : null}

      {ctaHref && data.cta_label ? (
        <div
          className={textCentered ? "flex justify-center" : undefined}
        >
          <a
            href={ctaHref}
            className={
              isHero
                ? `inline-flex items-center justify-center ${BLOCK_RADIUS_BUTTON_CLASS} border border-background bg-transparent px-6 py-3 text-sm font-medium text-background transition-colors duration-200 hover:bg-background hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-background motion-reduce:transition-none`
                : `inline-flex items-center justify-center ${BLOCK_RADIUS_BUTTON_CLASS} border border-primary bg-transparent px-6 py-3 text-sm font-medium text-primary transition-colors duration-200 hover:bg-primary hover:text-primary-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary motion-reduce:transition-none`
            }
          >
            {data.cta_label}
          </a>
        </div>
      ) : null}
    </div>
  );

  if (isHero) {
    return (
      <HeroFondoVideo
        label={data.title ?? "Sección de contenido"}
        imageUrl={imageUrl}
        videoUrl={videoUrl}
      >
        {text}
      </HeroFondoVideo>
    );
  }

  const image =
    hasImage && imageUrl ? (
      <div
        className={[
          "relative",
          imageAspectClass(data, DEFAULT_RICH_ASPECT),
          "w-full overflow-hidden",
          BLOCK_RADIUS_CLASS,
          imageFrameClass(data),
          "bg-card",
        ]
          .filter(Boolean)
          .join(" ")}
      >
        <img
          src={imageUrl}
          alt={data.title ? `Imagen: ${data.title}` : "Imagen de la sección"}
          width={800}
          height={1000}
          loading="lazy"
          decoding="async"
          className={["size-full", imageFitClass(data)].join(" ")}
        />
      </div>
    ) : null;

  return (
    <section
      aria-label={data.title ?? "Sección de contenido"}
      className={SECTION_ROOT_CLASS}
    >
      <div
        className={
          splitLayout
            ? "grid gap-10 md:grid-cols-2 md:items-center md:gap-14"
            : hasImage
              ? "grid gap-10"
              : undefined
        }
      >
        {splitLayout && imageSide === "left" ? (
          <>
            {image}
            {text}
          </>
        ) : (
          <>
            {text}
            {image}
          </>
        )}
      </div>
    </section>
  );
}

import type { ReactNode } from "react";
import { SECTION_ROOT_CLASS } from "../block-zone/types";

type HeroFondoVideoProps = {
  label: string;
  imageUrl?: string;
  videoUrl?: string;
  children: ReactNode;
};

/**
 * RichSection `fondo: completo` (#4567, hijo C de #4280). Full-bleed con media de fondo:
 * imagen (decorativa, `alt=""` + `aria-hidden`), `<video>` opcional encima (decorativo, sin
 * controles, muted/loop) y overlay fijo `bg-foreground/60`. El texto va en `children` con tono
 * inverso (`text-background`) para mantener AA sobre el overlay.
 * Fallback: sin video, o video que no carga, o reduce-motion → queda la imagen de fondo.
 * Solo video (sin imagen): la raíz lleva `bg-foreground` como base sólida; con reduce-motion o
 * video caído queda el overlay sobre ese color (texto inverso sigue en AA), no sobre el fondo
 * de página. Con imagen, la imagen cubre el 100% y esa base no se ve.
 * El caller solo lo usa si hay al menos imagen o video (sin media → render normal).
 */
export default function HeroFondoVideo({
  label,
  imageUrl,
  videoUrl,
  children,
}: HeroFondoVideoProps) {
  const isWebm = videoUrl
    ? new URL(videoUrl).pathname.toLowerCase().endsWith(".webm")
    : false;

  return (
    <section aria-label={label} className="relative w-full overflow-hidden bg-foreground">
      {imageUrl ? (
        <img
          src={imageUrl}
          alt=""
          aria-hidden="true"
          loading="lazy"
          decoding="async"
          className="absolute inset-0 size-full object-cover"
        />
      ) : null}

      {videoUrl ? (
        <video
          aria-hidden="true"
          autoPlay
          muted
          loop
          playsInline
          preload="metadata"
          poster={imageUrl}
          className="absolute inset-0 size-full object-cover motion-reduce:hidden"
        >
          <source src={videoUrl} type={isWebm ? "video/webm" : "video/mp4"} />
        </video>
      ) : null}

      <div className="absolute inset-0 bg-foreground/60" />

      <div className={`relative text-background ${SECTION_ROOT_CLASS}`}>
        {children}
      </div>
    </section>
  );
}
